#include "server1/archive/ZipSource.h"
#include <QCoreApplication>
#include <QTimer>
#include <QElapsedTimer>
#include <QFile>
#include <QtEndian>
#include <QJsonDocument>
#include <iostream>
using namespace server1::archive;
int main(int argc,char**argv){QCoreApplication app(argc,argv);int fail=0;auto check=[&](bool b,const char*m){if(!b){++fail;std::cerr<<m<<'\n';}};auto until=[&](auto p){QElapsedTimer t;t.start();while(!p()&&t.elapsed()<1000)app.processEvents(QEventLoop::AllEvents,10);check(p(),"timeout");};
 QFile golden(QString(argv[1])+"/../zip-oracle.json");if(!golden.open(QIODevice::ReadOnly))return 2;auto oracle=QJsonDocument::fromJson(golden.readAll()).object();
 for(auto v:oracle["ranges"].toArray()){auto o=v.toObject();ZipEntry e;e.size=10;e.dataOffset=100;e.method=o["compressed"].toBool()?8:0;auto p=zipRangePlan(e,o["method"].toString(),o["range"].toString());check(p.status==o["status"].toInt()&&p.contentRange==o["contentRange"].toString(),"exact route status/range");if(!o["contentLength"].isNull())check(p.contentLength==o["contentLength"].toVariant().toLongLong(),"exact route length");if(o["sourceRange"].isObject()){auto r=o["sourceRange"].toObject();check(p.sourceStart==r["start"].toInteger()&&p.sourceEnd==r["end"].toInteger(),"exact source interval");}}
 for(const QString filename:{"stored.zip","deflated.zip","long.zip","zip64.zip","bad.zip","truncated.zip"}){QFile f(QString(argv[1])+"/"+filename);if(!f.open(QIODevice::ReadOnly))return 2;QByteArray bytes=f.readAll();qint64 requested=0;QSet<quint64> cancelled;quint64 next=1;auto read=[&](qint64 offset,qint64 count,auto cb){auto token=next++;requested+=count;QTimer::singleShot(0,&app,[&,token,offset,count,cb](){if(cancelled.contains(token))return;ReadResult r;if(offset<0||offset+count>bytes.size())r.error="short source";else r.bytes=bytes.mid(offset,count);cb(r);});return token;};ZipSource zip(bytes.size(),read,[&](quint64 t){cancelled.insert(t);});bool done=false;zip.open([&](ZipDirectory d){if(filename=="bad.zip"||filename=="truncated.zip")check(d.error=="FILE_ENDED","bad archive exact error");else{check(d.error.isEmpty()&&d.entries.size()==1,"directory");if(!d.entries.isEmpty()){auto entry=d.entries[0];check(entry.size==200000&&entry.name.endsWith("video.mkv"),"metadata");zip.localEntry(entry,[&](ZipEntry e,QString error){check(error.isEmpty()&&e.dataOffset>0,"local data offset");done=true;});return;}}done=true;});until([&]{return done;});if(filename=="stored.zip")check(requested<1024,"no full archive download");}
 ZipEntry e;e.size=10;e.dataOffset=100;e.method=0;auto p=zipRangePlan(e,"GET","bytes=-3");check(p.status==206&&p.start==7&&p.end==9&&p.sourceStart==107&&p.sourceEnd==109,"suffix");check(zipRangePlan(e,"GET","bytes=10-").status==416,"416");check(zipRangePlan(e,"HEAD","").status==200&&zipRangePlan(e,"HEAD","").head,"stored HEAD");p=zipRangePlan(e,"GET","bytes=0-0");check(p.contentLength==1&&p.sourceEnd==110,"source zero-end quirk");e.method=8;check(zipRangePlan(e,"GET","bytes=1-").status==405,"deflate 405");check(zipRangePlan(e,"HEAD","").status==204,"deflate HEAD 204");check(zipRangePlan(e,"GET","bytes=0-9").status==200,"deflate full range");
 std::cout<<"failures="<<fail<<'\n';return fail?1:0;}
